def load_match_data(parsed_query: dict) -> dict:
    """Load and analyze match data based on query intent"""
    analyzer = MatchAnalyzer(data_path='data/match_data/results.csv')

    intent = parsed_query.get('intent')

    if intent == 'prediction' and len(parsed_query.get('teams', [])) >= 2:
        home_team = parsed_query['teams'][0]
        away_team = parsed_query['teams'][1]
        result = analyzer.predict_match(home_team, away_team)
        return {
            'type': 'prediction',
            'data': result,
            'query': parsed_query['query']
        }

    elif intent == 'analysis' and parsed_query.get('team'):
        team = parsed_query['team']
        result = analyzer.analyze_team(team, num_matches=10)
        return {
            'type': 'analysis',
            'data': result,
            'query': parsed_query['query']
        }

    return {
        'type': 'error',
        'message': 'Could not process query',
        'query': parsed_query['query']
    }

def format_response(ai_analysis: str, match_data: dict) -> str:
    """Format the final response with data and AI insights"""
    data_type = match_data.get('type', 'unknown')

    if data_type == 'prediction':
        pred = match_data['data'].get('prediction', {})
        response = f"""🎯 Match Prediction Analysis

Teams: {pred.get('home_team', 'N/A')} vs {pred.get('away_team', 'N/A')}

Predicted Probabilities:
- Home Win: {pred.get('home_win_prob', 0):.1%}
- Draw: {pred.get('draw_prob', 0):.1%}
- Away Win: {pred.get('away_win_prob', 0):.1%}

AI Tactical Analysis:
{ai_analysis}
"""

    elif data_type == 'analysis':
        stats = match_data['data'].get('statistics', {})
        form = match_data['data'].get('form', {})
        response = f"""📊 Team Performance Analysis

Team: {stats.get('team', 'N/A')}

Key Statistics:
- Win Rate: {stats.get('win_rate', 0):.1%}
- Matches Played: {stats.get('matches_played', 0)}
- Recent Form: {form.get('form_string', 'N/A')}
- Form Score: {form.get('form_score', 0):.1f}/100

AI Tactical Insights:
{ai_analysis}
"""

    else:
        response = f"Error: {match_data.get('message', 'Unknown error')}"

    return response
